/// <summary>
/// The QR code of a new device setup code, shown once (HSMobileOpsDeviceSetupCodeNew). The code is
/// not kept, so print or show it now; closing this loses it (make a new one then).
/// </summary>
[Form]
public class HSMobileOpsDeviceSetupQr extends FormRun
{
}

public void init()
{
    str setupText;

    super();
    setupText = element.args() ? element.args().parm() : '';
    if (!setupText)
    {
        throw error('Open this from New device setup code.');
    }
    QrText.text(setupText);
    QrImage.image(new Image(HSMobileOpsDeviceSetupCodeNew::qrPng(setupText)));
}
